<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigTimeoutAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigTimeoutAccessor trait.
 *
 * Covers null default, string/VO assignment via withTimeout,
 * getTimeout/timeout accessors, and isTimeoutChanged with/without original.
 */
class SmtpOutboundConfigTimeoutAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTimeout creates a new instance with the Timeout set
     * from a string value, and getTimeout returns the primitive string.
     */
    public function testWithTimeoutFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigTimeoutAccessorUnitTest();

        // Act
        $result = $holder->withTimeout(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getTimeout());
    }
    /**
     * Asserts that withtimeout has access to the value object
     * from a string value, and getTimeout returns the primitive string.
     */
    public function testWithTimeoutFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigTimeoutAccessorUnitTest();

        // Act
        $result = $holder->withTimeout(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->timeout()->value());
    }
    public function testChangedTimeout(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigTimeoutAccessorUnitTest()->withTimeout(1);
        $original = $holder->withTimeout(1);
        $same = $holder->withTimeout(1);
        $modified = $holder->withTimeout(2);

        // Act
        $withSame = $original->isTimeoutChanged($same);
        $withDiferent = $original->isTimeoutChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigTimeoutAccessorUnitTest
{
    use SmtpOutboundConfigTimeoutAccessor;
}
